+function parseVersion(s: string): Version {
+  const m = s.match(/^(\d+)\.(\d+)\.(\d+)$/);
+  if (!m) throw new Error();
+  const v: Version = [parseInt(m[1]), parseInt(m[2]), parseInt(m[3])];
+  if (String(v[0]) !== m[1] || String(v[1]) !== m[2] || String(v[2]) !== m[3]) {
+    throw new Error();
+  }
+  return v;
+}
